<?php
namespace Tests\Feature;
use App\Contracts\ProtectedMediaStorage;use App\Jobs\{GenerateMediaExport,ProcessMediaAsset,ReconcileStorageLedger};use App\Models\{Group,MediaAsset,MediaExport,MediaVariant,Photo,StorageLedgerEntry,UploadBatch,UploadBatchFile,User};use App\Services\Media\MediaVariantProcessor;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{Cache,Hash,Queue,Storage};use Illuminate\Support\Str;use Mockery;use RuntimeException;use Tests\TestCase;use ZipArchive;
class MediaFailurePathTest extends TestCase {use RefreshDatabase;protected function setUp():void{parent::setUp();config(['media.disk'=>'private_local','media.delivery_driver'=>'local','cache.default'=>'array','queue.default'=>'sync']);Storage::fake('private_local');Queue::fake();}private function user(string$e):User{return User::create(['name'=>'User','email'=>$e,'password'=>Hash::make('x'),'status'=>'active','account_type'=>'photographer']);}private function group(User$u):Group{$g=Group::create(['name'=>'Event','creator_id'=>$u->id,'downloads_enabled'=>true]);$g->members()->attach($u->id,['role'=>'admin','membership_status'=>'active','access_type'=>'full_access']);return$g;}private function batch(Group$g,User$u,int$n=1):UploadBatch{return UploadBatch::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'total_files'=>$n,'pending_files'=>$n]);}private function asset(Group$g,User$u,string$key,bool$stored=true):array{if($stored)Storage::disk('private_local')->put($key,$this->jpeg());$p=Photo::create(['group_id'=>$g->id,'uploader_id'=>$u->id,'filename'=>'x.jpg','original_filename'=>'x.jpg','path'=>$key,'thumbnail_path'=>$key,'file_size'=>Storage::disk('private_local')->exists($key)?Storage::disk('private_local')->size($key):1,'mime_type'=>'image/jpeg']);$a=MediaAsset::create(['uuid'=>(string)Str::uuid(),'photo_id'=>$p->id,'group_id'=>$g->id,'owner_id'=>$u->id,'uploader_id'=>$u->id,'storage_disk'=>'private_local','original_object_key'=>$key,'original_filename'=>'x.jpg','mime_type'=>'image/jpeg','size_bytes'=>$p->file_size,'checksum_sha256'=>str_repeat('a',64),'state'=>'queued']);MediaVariant::create(['media_asset_id'=>$a->id,'variant_type'=>'original','storage_disk'=>'private_local','object_key'=>$key,'mime_type'=>'image/jpeg','size_bytes'=>$p->file_size,'checksum_sha256'=>str_repeat('a',64),'state'=>'ready']);return[$a,$p];}
 public function test_transient_failure_then_retry_succeeds():void{[$u,$g]=[$this->user('a@x.test'),null];$g=$this->group($u);[$a]=$this->asset($g,$u,'media/originals/a.jpg');$b=$this->batch($g,$u);$f=UploadBatchFile::create(['upload_batch_id'=>$b->id,'media_asset_id'=>$a->id,'client_filename'=>'a.jpg']);$processor=Mockery::mock(MediaVariantProcessor::class);$processor->shouldReceive('process')->once()->andThrow(new RuntimeException('transient'));$processor->shouldReceive('process')->once()->andReturnNull();$job=new ProcessMediaAsset($a->id,$f->id);try{$job->handle($processor);$this->fail('Expected transient failure');}catch(RuntimeException){}$this->assertSame('failed',$f->fresh()->state);$job->handle($processor);$this->assertSame('completed',$f->fresh()->state);$this->assertSame(2,$f->fresh()->attempts);}
 public function test_duplicate_processing_is_idempotent_and_overlap_lock_is_real():void{$u=$this->user('b@x.test');$g=$this->group($u);[$a]=$this->asset($g,$u,'media/originals/b.jpg');$processor=app(MediaVariantProcessor::class);$processor->process($a);$processor->process($a->fresh());$this->assertSame(3,$a->variants()->count());$this->assertSame(2,StorageLedgerEntry::where('media_asset_id',$a->id)->count());$job=new ProcessMediaAsset($a->id);$mw=$job->middleware()[0];$lock=Cache::lock($mw->getLockKey($job),240);$this->assertTrue($lock->get());$ran=false;$mw->handle($job,function()use(&$ran){$ran=true;});$this->assertFalse($ran);$lock->release();}
 public function test_zip_contains_only_authorized_existing_media_with_safe_unique_names():void{$u=$this->user('c@x.test');$g=$this->group($u);[, $p1]=$this->asset($g,$u,'media/originals/c1.jpg');[, $missing]=$this->asset($g,$u,'media/originals/missing.jpg',false);$otherUser=$this->user('d@x.test');$other=$this->group($otherUser);[, $inaccessible]=$this->asset($other,$otherUser,'media/originals/c2.jpg');$e=MediaExport::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'state'=>'queued','photo_ids'=>[$p1->id,$missing->id,$inaccessible->id]]);(new GenerateMediaExport($e->id))->handle(app(ProtectedMediaStorage::class));$e->refresh();$this->assertSame('completed',$e->state);$bytes=Storage::disk('private_local')->get($e->object_key);$tmp=tempnam(sys_get_temp_dir(),'zip-check-');file_put_contents($tmp,$bytes);$zip=new ZipArchive;$zip->open($tmp);$this->assertSame(1,$zip->numFiles);$name=$zip->getNameIndex(0);$this->assertMatchesRegularExpression('/^photo-\d+-[0-9a-f-]{36}\.jpg$/',$name);$this->assertStringNotContainsString('..',$name);$zip->close();unlink($tmp);}
 public function test_mid_zip_failure_cleans_temp_and_never_exposes_download():void{$u=$this->user('e@x.test');$g=$this->group($u);[, $p1]=$this->asset($g,$u,'media/originals/e1.jpg');[, $p2]=$this->asset($g,$u,'media/originals/e2.jpg');$e=MediaExport::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'state'=>'queued','photo_ids'=>[$p1->id,$p2->id]]);$before=glob(sys_get_temp_dir().'/lenspic-export-*');$storage=Mockery::mock(ProtectedMediaStorage::class);$storage->shouldReceive('exists')->twice()->andReturnTrue();$storage->shouldReceive('readStream')->once()->andReturnUsing(function(){$s=fopen('php://temp','r+');fwrite($s,'one');rewind($s);return$s;});$storage->shouldReceive('readStream')->once()->andThrow(new RuntimeException('injected'));try{(new GenerateMediaExport($e->id))->handle($storage);$this->fail('Expected injected failure');}catch(RuntimeException){}$this->assertEqualsCanonicalizing($before,glob(sys_get_temp_dir().'/lenspic-export-*'));$this->assertSame('failed',$e->fresh()->state);$this->assertNull($e->fresh()->object_key);$this->actingAs($u)->get(route('exports.download',$e))->assertStatus(410);}
 public function test_ledger_is_consistent_after_failed_then_retried_processing():void{$u=$this->user('f@x.test');$g=$this->group($u);[$a]=$this->asset($g,$u,'media/originals/retry.jpg',false);$processor=app(MediaVariantProcessor::class);try{$processor->process($a);$this->fail('Expected missing source');}catch(RuntimeException){}$this->assertSame(0,StorageLedgerEntry::where('owner_id',$u->id)->sum('byte_delta'));$this->assetBytes('media/originals/retry.jpg');$processor->process($a);(new ReconcileStorageLedger($u->id))->handle();$this->assertSame((int)StorageLedgerEntry::where('owner_id',$u->id)->sum('byte_delta'),(int)$u->fresh()->storage_used);}
 public function test_partial_batch_failure_keeps_successful_file_completed():void{$u=$this->user('g@x.test');$g=$this->group($u);[$ok]=$this->asset($g,$u,'media/originals/ok.jpg');[$bad]=$this->asset($g,$u,'media/originals/bad.jpg',false);$b=$this->batch($g,$u,2);$one=UploadBatchFile::create(['upload_batch_id'=>$b->id,'media_asset_id'=>$ok->id,'client_filename'=>'ok.jpg']);$two=UploadBatchFile::create(['upload_batch_id'=>$b->id,'media_asset_id'=>$bad->id,'client_filename'=>'bad.jpg']);(new ProcessMediaAsset($ok->id,$one->id))->handle(app(MediaVariantProcessor::class));try{(new ProcessMediaAsset($bad->id,$two->id))->handle(app(MediaVariantProcessor::class));}catch(RuntimeException){}$b->refreshCounts();$this->assertSame('completed',$one->fresh()->state);$this->assertSame('failed',$two->fresh()->state);$this->assertSame('partially_completed',$b->fresh()->state);}
 private function assetBytes(string$key):void{Storage::disk('private_local')->put($key,$this->jpeg());}
private function jpeg():string{$im=imagecreatetruecolor(8,8);$color=imagecolorallocate($im,20,40,60);imagefill($im,0,0,$color);ob_start();imagejpeg($im,null,85);$bytes=(string)ob_get_clean();imagedestroy($im);return $bytes;}
}
